from pathlib import Path
import importlib.util
import json
import re
import sys
from types import ModuleType, SimpleNamespace
from urllib.parse import parse_qsl, urlsplit

have_flask = importlib.util.find_spec(\"flask\") is not None
if not have_flask:
    class Blueprint:
        def __init__(self, name, import_name):
            self.rules = {}

        def route(self, method, path):
            def register(handler):
                self.rules[method, path] = handler
                return handler
            return register

        def get(self, path):
            return self.route(\"GET\", path)

        def post(self, path):
            return self.route(\"POST\", path)

    class Flask:
        def __init__(self, name):
            self.rules = {}

        def register_blueprint(self, blueprint, url_prefix):
            self.rules.update(
                {(method, url_prefix + path): handler
                 for (method, path), handler in blueprint.rules.items()}
            )

    request = SimpleNamespace()
    flask = ModuleType(\"flask\")
    flask.Flask, flask.Blueprint, flask.request = Flask, Blueprint, request
    flask.jsonify = lambda payload: payload
    sys.modules[\"flask\"] = flask

from app import create_app
from app.routes.orders import STATUSES

app = create_app()
if have_flask:
    client = app.test_client()
    registered = {(method, rule.rule)
                  for rule in app.url_map.iter_rules()
                  for method in rule.methods if method in (\"GET\", \"POST\")}
else:
    registered = set(app.rules)

doc = Path(\"docs/interfaces/Order_API_Doc.md\").read_text()
anchors = re.findall(r'<a id=\"(["'^"]+)"></a>'"', doc)
links = re.findall(r'\\[["'^'"\\]]+\\]\\(#(["'^)]+)'"\\)', doc)
assert len(anchors) == len(set(anchors))
assert set(links) <= set(anchors), set(links) - set(anchors)

operations = re.findall(r'"'^'"\\| \\[["'^'"\\]]+\\]\\(#(["'^)]+)'"\\) \\| (GET|POST) \\| "'`([''^`]+)` '"\\|"'$'"', doc, re.M)
assert re.search(rf\"共 {len(operations)} 个 HTTP 接口\", doc)
sections = doc.split(\"## 3. 接口详情\\n\", 1)[1].split(\"## 4. 数据类型\", 1)[0]
details = dict(re.findall(
    r'<a id=\"(["'^"]+)"></a>'"\\s*### ["'^'"\\n]+\\s*"'`((?:GET|POST) /shop[''^`]+)`'"',
    sections,
))
assert details == {anchor: f\"{method} /shop{path}\" for anchor, method, path in operations}
assert {(method, re.sub(r\"{(\\w+)}\", r\"<\\1>\", path)) for _, method, path in operations} == {
    (method, path) for method, path in registered if path.startswith(\"/api/v1/orders\")
}
assert tuple(re.findall(r'"'^'"\\| "'`([A-Z]+)` '"\\|', doc, re.M)) == STATUSES

def invoke(method, route, *, order_id=None, body=None, query=\"\", signed_in=True):
    headers = {\"X-User-Id\": \"test-user\"} if signed_in else {}
    if have_flask:
        url = route.replace(\"<order_id>\", order_id or \"\") + query
        response = client.open(url, method=method, headers=headers, json=body)
        return response.status_code, response.get_json(silent=True)

    request.headers = headers
    request.args = dict(parse_qsl(urlsplit(query).query, keep_blank_values=True))
    request.get_json = lambda silent=True: body
    args = {} if order_id is None else {\"order_id\": order_id}
    output = app.rules[method, route](**args)
    if isinstance(output, tuple):
        payload, status = output
        return status, payload
    return 200, output

def fail(status, code, msg):
    return status, {\"code\": code, \"msg\": msg, \"data\": None}

def success(data):
    return 200, {\"code\": 0, \"msg\": \"ok\", \"data\": data}

create_req, create_res, detail_res, list_res, cancel_req, cancel_res = [
    json.loads(example) for example in re.findall(r\""'```json'"\\n(.*?)\\n"'```", doc, re.S)
]
base = "/api/v1/orders"
order_id = create_res["data"]["orderId"]
detail = base + "/<order_id>"
cancel = detail + "/cancel"
assert invoke("POST", base, body=create_req) == (200, create_res)
assert invoke("GET", detail, order_id=order_id) == (200, detail_res)
assert invoke("GET", base, query="?page=1&size=20&status=PAID") == (200, list_res)
assert invoke("POST", cancel, order_id=order_id, body=cancel_req) == (200, cancel_res)

for method, path in registered:
    if path.startswith(base):
        assert invoke(method, path, order_id=order_id if "<" in path else None, signed_in=False) == fail(
            401, 40100, "unauthorized"
        )
for body in [None, {}, {"items": None}, {"items": []}]:
    assert invoke("POST", base, body=body) == fail(400, 40001, "items required")
for item in [{}, {"skuId": "SKU123"}, {"skuId": "SKU123", "qty": 0}, {"skuId": "", "qty": 1}]:
    assert invoke("POST", base, body={"items": [item]}) == fail(400, 40002, "invalid item")
items = [{"skuId": "b", "qty": "2"}, {"skuId": "a", "qty": 3}]
assert invoke("POST", base, body={"items": items, "remark": None, "couponCode": ""}) == success({
    "orderId": order_id, "status": "CREATED", "items": [{"skuId": "b", "qty": 2}, items[1]],
    "remark": None, "couponCode": "",
})
assert invoke("POST", base, body={"items": items})[1]["data"]["remark"] == ""
assert invoke("GET", detail, order_id="invalid") == fail(404, 40400, "order not found")
assert invoke("GET", base, query="?status=") == (200, list_res)
assert invoke("GET", base, query="?status=paid") == fail(400, 40003, "invalid status")
assert invoke("GET", base, query="?page=2&size=101") == success({
    "page": 2, "size": 100, "total": 0, "list": [],
})
for body in [None, {}, {"reason": None}, {"reason": ""}]:
    assert invoke("POST", cancel, order_id=order_id, body=body) == success({
        "orderId": order_id, "status": "CANCELLED", "reason": (body or {}).get("reason"),
    })
for method, body, query in [
    ("GET", None, "?page="), ("GET", None, "?size=bad"),
    ("POST", {"items": [{"skuId": "SKU123", "qty": None}]}, ""),
]:
    if have_flask:
        assert invoke(method, base, body=body, query=query)[0] == 500
    else:
        try:
            invoke(method, base, body=body, query=query)
        except (TypeError, ValueError):
            pass
        else:
            raise AssertionError((method, body, query))

print(f"Verified {len(operations)} route declarations, {len(anchors)} anchors, six JSON examples, auth, errors, and defaults.")
print("Execution mode:", "Flask test client" if have_flask else "handler calls with stubbed Flask transport")
